from typing import Dict, List, Optional, Tuple
from collections import Counter, OrderedDict, defaultdict, deque
import heapq

def is_isomorphic(s: str, t: str) -> bool:
    sto: dict[str, str] = {}
    tso: dict[str, str] = {}
    for a, b in zip(s, t):
        if a in sto and sto[a] != b:
            return False
        if b in tso and tso[b] != a:
            return False
        sto[a] = b
        tso[b] = a
    return True
